B64=$(cat /tmp/appendix_full.b64) && python3 << PYEOF
b64 = open('/tmp/appendix_full.b64').read().strip()
# Test: does the b64 contain any characters that could break a shell single-quote string?
bad_chars = set()
for c in b64:
    if c not in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=':
        bad_chars.add(c)
if bad_chars:
    print(f"WARNING: Bad chars found: {bad_chars}")
else:
    print("All chars are safe base64 characters")
PYEOF
